function pop(stack):
  if stack.size == 0:
    return null
  stack.size = stack.size - 1
  return stack.data[stack.size]

function append(arr, value):
  if arr.size == arr.capacity:
    resize(arr, arr.capacity * 2)
  arr.data[arr.size] = value
  arr.size = arr.size + 1

