function twoSum(arr, target):
  seen = map()
  for i in 0..arr.length:
    need = target - arr[i]
    if need in seen:
      return [seen[need], i]
    seen[arr[i]] = i

function isPalindrome(s):
  left = 0
  right = s.length - 1
  while left < right:
    if s[left] != s[right]:
      return false
    left = left + 1
    right = right - 1
  return true

function maxInWindow(arr, k):
  windowSum = 0
  for i in 0..k:
    windowSum = windowSum + arr[i]
  best = windowSum
  for i in k..arr.length:
    windowSum = windowSum + arr[i] - arr[i - k]
    best = max(best, windowSum)
  return best

function height(node):
  if node == null:
    return 0
  return 1 + max(height(node.left), height(node.right))

function bstSearch(node, target):
  if node == null:
    return false
  if node.value == target:
    return true
  if target < node.value:
    return bstSearch(node.left, target)
  return bstSearch(node.right, target)

function searchSkewed(node, target):
  while node != null:
    if node.value == target:
      return true
    node = node.right
  return false
