function floydWarshall(dist):
  n = dist.length
  for k in 0..n:
    for i in 0..n:
      for j in 0..n:
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

function solveNQueens(n, row, cols):
  if row == n:
    return 1
  count = 0
  for col in 0..n:
    if isSafe(row, col, cols):
      cols[row] = col
      count = count + solveNQueens(n, row + 1, cols)
  return count

