function sumArray(arr, index):
  if index == arr.length:
    return 0
  return arr[index] + sumArray(arr, index + 1)

function majority(arr):
  candidate = null
  count = 0
  for x in arr:
    if count == 0:
      candidate = x
      count = 1
    else if x == candidate:
      count = count + 1
    else:
      count = count - 1
  return candidate

function hasCycle(head):
  slow = head
  fast = head
  while fast != null and fast.next != null:
    slow = slow.next
    fast = fast.next.next
    if slow == fast:
      return true
  return false

function sortColors(arr):
  low = 0
  mid = 0
  high = arr.length - 1
  while mid <= high:
    if arr[mid] == 0:
      swap(arr[low], arr[mid]); low++; mid++
    else if arr[mid] == 2:
      swap(arr[mid], arr[high]); high--
    else:
      mid++

function topoDFS(node, visited, order):
  visited.add(node)
  for next in node.neighbors:
    if next not in visited:
      topoDFS(next, visited, order)
  order.push(node)

